def finish(sections, lang):
    """Append the practice drills (shared, language-specific data) to the practice section."""
    for sec in sections:
        if sec["id"] == "practice" and not any(b[0] == "drill" for b in sec["blocks"]):
            sec["blocks"].extend(deriv_drills.drill_blocks(lang))
    return sections


finish(RU, "ru")
EN = RU  # replaced by the translations
UZ = RU
SECTIONS = {"ru": RU, "en": EN, "uz": UZ}


def check_numbers():
    import math
    import sympy as sp
    deriv_drills.verify()
    x, y, z, t, D = sp.symbols("x y z t D", real=True)
    ok = lambda e: sp.simplify(e) == 0
    # increments around x = 3
    for dx, dy, q in ((1, 7, 7), (0.1, 0.61, 6.1), (0.01, 0.0601, 6.01), (0.001, 0.006001, 6.001), (-0.001, -0.005999, 5.999)):
        assert abs((3 + dx) ** 2 - 9 - dy) < 1e-12 and abs(((3 + dx) ** 2 - 9) / dx - q) < 1e-9, dx
    # slope
    assert (4 - 1) / (2 - 0) == 1.5 and (7 - 1) / 4 == 1.5 and (2.5 + 2) / 3 == 1.5
    # the tail table at x = 1
    for dx, df, lin, tail, share, q in ((1, 3, 2, 1, 33.3, 3), (0.5, 1.25, 1, 0.25, 20, 2.5), (0.1, 0.21, 0.2, 0.01, 4.76, 2.1), (0.01, 0.0201, 0.02, 0.0001, 0.498, 2.01), (0.001, 0.002001, 0.002, 0.000001, 0.05, 2.001)):
        assert abs((1 + dx) ** 2 - 1 - df) < 1e-12 and abs(2 * dx - lin) < 1e-12 and abs(dx * dx - tail) < 1e-15 and abs(df / dx - q) < 1e-9
        assert float(f"{tail / df * 100:.3g}") == share, (dx, tail / df * 100)
    # derivative examples and the tangent
    assert ok(sp.limit(((x + D) ** 2 - x ** 2) / D, D, 0) - 2 * x)
    assert ok(sp.limit(((x + D) ** 3 - x ** 3) / D, D, 0) - 3 * x ** 2)
    assert ok(sp.expand(x ** 2 - (2 * x - 1)) - (x - 1) ** 2)
    assert abs(math.sqrt(4.1) - 2.024845673) < 1e-9 and 2 + 0.25 * 0.1 == 2.025
    # existence
    assert sp.limit(sp.Abs(D) / D, D, 0, "+") == 1 and sp.limit(sp.Abs(D) / D, D, 0, "-") == -1
    assert sp.limit(D * sp.sin(1 / D), D, 0) == 0
    # the table
    for f, d in ((sp.sqrt(x), 1 / (2 * sp.sqrt(x))), (1 / x, -1 / x ** 2), (sp.exp(x), sp.exp(x)), (sp.log(x), 1 / x), (sp.sin(x), sp.cos(x)), (sp.cos(x), -sp.sin(x)), (sp.exp(x * sp.log(2)), sp.exp(x * sp.log(2)) * sp.log(2))):
        lim = sp.limit((f.subs(x, x + D) - f) / D, D, 0)
        assert ok(lim - d) or abs(float((lim - d).subs(x, 0.7))) < 1e-12, (f, lim)
    # partials and the gradient
    F = x ** 2 * y + y ** 3
    assert ok(sp.diff(F, x) - 2 * x * y) and ok(sp.diff(F, y) - (x ** 2 + 3 * y ** 2))
    G = x ** 2 * y + sp.sin(y)
    assert [sp.diff(G, v).subs({x: 1, y: 0}) for v in (x, y)] == [0, 2]
    H = x ** 2 * y + sp.sin(z)
    assert [sp.diff(H, v) for v in (x, y, z)] == [2 * x * y, x ** 2, sp.cos(z)]
    bowl = x ** 2 + y ** 2
    assert [sp.diff(bowl, v).subs({x: -1, y: sp.Rational(1, 2)}) for v in (x, y)] == [-2, 1]
    assert [sp.diff(bowl, v).subs({x: 1, y: 2}) for v in (x, y)] == [2, 4]
    # directional derivative
    expr = bowl.subs({x: 3 - sp.Rational(3, 5) * t, y: 4 - sp.Rational(4, 5) * t})
    assert ok(sp.expand(expr) - (25 - 10 * t + t ** 2)) and sp.limit((expr - 25) / t, t, 0) == -10
    # total differential of x²y at (2, 3)
    for (dx, dy), dfv, Dfv, tail in (((0.1, 0.2), 2, 2.112, 0.112), ((0.01, 0.02), 0.2, 0.201102, 0.001102), ((0.001, 0.002), 0.02, 0.020011, 0.000011)):
        df = 12 * dx + 4 * dy; Df = (2 + dx) ** 2 * (3 + dy) - 12
        assert abs(df - dfv) < 1e-12 and round(Df, 6) == Dfv and round(Df - df, 6) == tail, (dx, Df, Df - df)
    # the non-differentiable example
    g = x * y / (x ** 2 + y ** 2)
    assert sp.limit(g.subs({x: D, y: 0}) / D, D, 0) == 0 and ok(g.subs(y, x) - sp.Rational(1, 2))
    # descent
    p = (3.0, 4.0)
    rows = [((3, 4), (6, 8), 25), ((2.4, 3.2), (4.8, 6.4), 16), ((1.92, 2.56), (3.84, 5.12), 10.24), ((1.536, 2.048), (3.072, 4.096), 6.5536)]
    for (pp, gg, fv) in rows:
        assert all(abs(a - b) < 1e-9 for a, b in zip(p, pp)) and all(abs(2 * a - b) < 1e-9 for a, b in zip(p, gg)) and abs(p[0] ** 2 + p[1] ** 2 - fv) < 1e-9
        p = (p[0] - 0.1 * 2 * p[0], p[1] - 0.1 * 2 * p[1])
    for eta, q in ((0.1, 0.8), (0.3, 0.4), (0.5, 0), (0.8, -0.6), (1, -1), (1.1, -1.2)):
        assert abs(1 - 2 * eta - q) < 1e-12
    # extremum
    E = bowl - 2 * x + 4 * y
    assert sp.solve([sp.diff(E, x), sp.diff(E, y)], [x, y]) == {x: 1, y: -2} and E.subs({x: 1, y: -2}) == -5
    assert ok(E - ((x - 1) ** 2 + (y + 2) ** 2 - 5))
    # sin 4 example not used; quiz: η = 1 → −1
    return True


if __name__ == "__main__":
    print("numbers ok" if check_numbers() else "")
